// Internal webhooks are only meant to be called by the Elliot dashboard's
// server (or by you, by hand). The caller must send the shared secret in an
// `x-elliot-webhook-secret` header; it's compared against this n8n instance's
// ELLIOT_WEBHOOK_SECRET env var. Unset secret => every call is rejected
// (fail closed), so a fresh n8n without the env var can't be abused either.
// See docs/workflow-specs/internal-webhook-auth.md.
const item = $input.first().json;
const expected = String($env.ELLIOT_WEBHOOK_SECRET || '');
const headers = item.headers || {};
const provided = String(headers['x-elliot-webhook-secret'] || '');

// Length check first, then a constant-time comparison of equal-length strings.
let authorized = expected.length >= 16 && provided.length === expected.length;
if (authorized) {
  let diff = 0;
  for (let i = 0; i < expected.length; i++) diff |= expected.charCodeAt(i) ^ provided.charCodeAt(i);
  authorized = diff === 0;
}

// Pass the original webhook item through untouched (body, headers, query) so
// the existing Validate Input node keeps reading $input.first().json.body.
return [{ json: { ...item, _authorized: authorized } }];
